using UnityEngine;
using UnityEngine.UI;

public sealed class TapToRevealLesson : MonoBehaviour
{
    [SerializeField] private Camera arCamera;
    [SerializeField] private Collider revealTarget;
    [SerializeField] private GameObject lessonModel;
    [SerializeField] private Text caption;
    [TextArea]
    [SerializeField] private string lessonCaption = "Observe how the labeled structure connects to the surrounding tissue.";

    private void Awake()
    {
        if (lessonModel != null)
        {
            lessonModel.SetActive(false);
        }
    }

    private void Update()
    {
        if (Input.touchCount == 0)
        {
            return;
        }

        Touch touch = Input.GetTouch(0);
        if (touch.phase != TouchPhase.Began || arCamera == null ||
            revealTarget == null || lessonModel == null)
        {
            return;
        }

        Ray ray = arCamera.ScreenPointToRay(touch.position);
        if (Physics.Raycast(ray, out RaycastHit hit) && hit.collider == revealTarget)
        {
            lessonModel.SetActive(true);
            if (caption != null)
            {
                caption.text = lessonCaption;
            }
        }
    }
}

using UnityEngine;
using UnityEngine.UI;

public sealed class GuidedLessonSequence : MonoBehaviour
{
    [SerializeField] private GameObject[] stageModels;
    [SerializeField] private string[] stageCaptions;
    [SerializeField] private Text instructionText;

    private int currentStage;

    private void Start()
    {
        ShowStage(0);
    }

    public void NextStage()
    {
        if (stageModels == null || stageModels.Length == 0)
        {
            return;
        }

        currentStage = Mathf.Clamp(currentStage + 1, 0, stageModels.Length - 1);
        ShowStage(currentStage);
    }

    public void PreviousStage()
    {
        if (stageModels == null || stageModels.Length == 0)
        {
            return;
        }

        currentStage = Mathf.Clamp(currentStage - 1, 0, stageModels.Length - 1);
        ShowStage(currentStage);
    }

    private void ShowStage(int stageIndex)
    {
        if (stageModels == null || stageModels.Length == 0)
        {
            if (instructionText != null)
            {
                instructionText.text = string.Empty;
            }
            return;
        }

        currentStage = Mathf.Clamp(stageIndex, 0, stageModels.Length - 1);
        for (int i = 0; i < stageModels.Length; i++)
        {
            if (stageModels[i] != null)
            {
                stageModels[i].SetActive(i == currentStage);
            }
        }

        if (instructionText != null)
        {
            string caption = stageCaptions != null && currentStage < stageCaptions.Length
                ? stageCaptions[currentStage]
                : string.Empty;
            instructionText.text = $"Step {currentStage + 1} of {stageModels.Length}: {caption}";
        }
    }
}
